/**
 * Shared data types for the Kenya Childhood Malnutrition dashboard.
 *
 * These types describe the shape of `web/data/malnutrition_data.json`
 * (generated by the Python pipeline in `src/models/`) plus small UI
 * helpers shared by chart, table and map components.
 */

export type RiskLevel = 'low' | 'moderate' | 'high' | 'critical';

/** One row of the per-county prediction summary table. */
export interface CountySummary {
  county: string;
  acute_malnutrition_cases: number;
  predicted_cases: number;
  mae: number;
}

/** Monthly national actual vs predicted case counts. */
export interface NationalTrend {
  dates: string[];
  actual: number[];
  predicted: number[];
}

/** Monthly actual vs predicted series for a single county. */
export interface CountySeries {
  dates: string[];
  actual: number[];
  predicted: number[];
}

/** One data-quality check reported by the validation pipeline. */
export interface ValidationIssue {
  check: string;
  issue: string;
}

/** Root shape of `web/data/malnutrition_data.json`. */
export interface MalnutritionData {
  summary: CountySummary[];
  national_trend: NationalTrend;
  county_series: Record<string, CountySeries>;
  counties: string[];
  validation_issues: ValidationIssue[];
  generated_at: string;
  total_records: number;
  date_range: { start: string; end: string };
}

/**
 * Classify a county's predicted caseload into a risk bucket.
 * Thresholds mirror the heuristic predictor in `app/api/predict/route.ts`:
 *   > 5000 critical · > 2000 high · > 500 moderate · otherwise low.
 */
export function getRiskLevel(predicted: number): RiskLevel {
  if (predicted > 5000) return 'critical';
  if (predicted > 2000) return 'high';
  if (predicted > 500) return 'moderate';
  return 'low';
}

/** Tailwind chip classes (text + border + background) for a risk level. */
export function getRiskColor(level: RiskLevel): string {
  switch (level) {
    case 'critical':
      return 'bg-red-50 text-red-700 border-red-200';
    case 'high':
      return 'bg-orange-50 text-orange-700 border-orange-200';
    case 'moderate':
      return 'bg-amber-50 text-amber-700 border-amber-200';
    default:
      return 'bg-emerald-50 text-emerald-700 border-emerald-200';
  }
}

/** Tailwind dot background class for the small status circle in a chip. */
export function getRiskDot(level: RiskLevel): string {
  switch (level) {
    case 'critical':
      return 'bg-red-500';
    case 'high':
      return 'bg-orange-500';
    case 'moderate':
      return 'bg-amber-400';
    default:
      return 'bg-emerald-500';
  }
}
